import {topics, getTopic, deck, weekly, diagnostic} from './content.js';
const KEY='parole-b2-v1';
const DEFAULT={version:1,preferences:{rate:0.96,autoSpeak:true},reviews:{},sessions:[],lessons:[],active:null};
let data=load();
let ui={cardIndex:0,flipped:false,cardDone:false,route:'',draft:'',viaMic:false,asrUncertain:false,interim:'',listening:false,recognition:null,waiting:false,aiAvailable:false,aiModel:'',lessonChoice:null,checked:false,exerciseIndex:0,answerDraft:'',saving:false,showTextInExam:false,reviewQueue:null};
const $=s=>document.querySelector(s), app=$('#app');
function load(){try{const v=JSON.parse(localStorage.getItem(KEY));return v?.version===1?{...DEFAULT,...v,preferences:{...DEFAULT.preferences,...v.preferences}}:structuredClone(DEFAULT)}catch{return structuredClone(DEFAULT)}}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmt(d){return new Intl.DateTimeFormat('fr-FR',{day:'numeric',month:'long',year:'numeric'}).format(new Date(d))}
function uid(){return crypto?.randomUUID?.()||'id-'+Date.now()+'-'+Math.random().toString(16).slice(2)}
function fmtTime(s){s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function calcStreak(){const days=new Set(data.sessions.map(x=>new Date(x.endedAt).toLocaleDateString('en-CA')));let count=0;const d=new Date();if(!days.has(d.toLocaleDateString('en-CA')))d.setDate(d.getDate()-1);while(days.has(d.toLocaleDateString('en-CA'))){count++;d.setDate(d.getDate()-1)}return count}
function doneDays(){return new Set(data.sessions.filter(s=>s.mode==='guide').map(s=>s.day))}
function currentDay(){const done=doneDays();return topics.find(t=>!done.has(t.day))?.day||30}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),3500)}
function icons(day){return ['💬','✈️','💼','🤖','🩺','🚌','🌿','🗺️','📚','🛍️','🤝','🏡','🌎','📰','🎓','☁️','🥗','🏃','🔒','📱','⚖️','🏛️','🗣️','⚙️','👥','🎓','🧒','🏘️','⚡','✨'][(day-1)%30]}
const nav=[['accueil','⌂','Accueil'],['parcours','▦','Parcours'],['studio','◉','Studio oral'],['mes-erreurs','✎','Mes erreurs'],['progres','↗','Progrès']];
function pageTitle(route){return route.startsWith('cartes')?'Cartes de vocabulaire':route.startsWith('studio')?'Studio oral':route.startsWith('bilan')?'Mon bilan':route.startsWith('lecon')?'Ma leçon':route.startsWith('jour')?'Thématique du jour':route==='parcours'?'Parcours 30 jours':route==='mes-erreurs'?'Mes erreurs':route==='progres'?'Mes progrès':route==='parametres'?'Paramètres':'Mon espace'}
function shell(content,route){const active=route.split('/')[0];const navHtml=nav.map(([path,icon,label])=>`<a href="#/${path}" class="nav-item ${active===path?'active':''}"><span class="nav-emoji">${icon}</span><span class="nav-label">${label}</span></a>`).join('');const bottomHtml=nav.map(([path,icon,label])=>`<a href="#/${path}" class="${active===path?'active':''}"><span class="nav-emoji">${icon}</span><span>${label}</span></a>`).join('');return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">❝</div><div><div class="brand-title">Parole B2</div><div class="brand-sub">Votre voix, votre progrès.</div></div></div><div class="nav-list">${navHtml}</div><div class="sidebar-bottom"><div class="sidebar-week"><span style="font-size:11px;color:#c8b6fb">VOTRE PARCOURS</span><b>De B1 vers B2</b><p>30 jours pour prendre confiance à l'oral.</p><a class="btn small light block" href="#/parametres">⚙ Paramètres</a></div></div></aside><main class="main"><header class="topbar"><span class="crumb">Parole B2 <span style="opacity:.45">/</span> ${esc(pageTitle(route))}</span><div class="top-actions"><span class="tag neutral">🎯 Objectif DELF B2</span><a class="avatar" href="#/parametres" aria-label="Paramètres">B2</a></div></header>${content}</main><nav class="bottom-nav" aria-label="Navigation principale">${bottomHtml}</nav></div>`}
function linkBtn(href,text,style='primary',extra=''){return `<a class="btn ${style} ${extra}" href="${href}">${text}</a>`}
function btn(action,text,style='primary',attrs=''){return `<button type="button" class="btn ${style}" data-action="${action}" ${attrs}>${text}</button>`}
function nextStage(stage){return `<div class="step-track" aria-label="Parcours de la séance">${['cartes','studio','bilan','lecon'].map((s,i)=>`<span class="${i<=['cartes','studio','bilan','lecon'].indexOf(stage)?'lit':''}" title="${s}"></span>`).join('')}</div>`}
function title(label,heading,sub,aside=''){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${heading}</h1><p>${sub}</p></div>${aside}</div>`}
function dayCard(t){const done=doneDays().has(t.day);return `<a class="card topic-card" href="#/jour/${t.day}"><div class="row between"><span class="topic-icon">${icons(t.day)}</span><span class="tag ${done?'green':'neutral'}">${done?'✓ Terminé':'Jour '+t.day}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.objective)}</p><div class="foot"><span class="eyebrow">${esc(t.theme)}</span><span style="color:var(--violet);font-size:19px">↗</span></div></a>`}
function home(){const d=currentDay(),t=getTopic(d),done=doneDays(),known=Object.values(data.reviews).filter(r=>r.rating==='known').length;return `${title('VOTRE PARCOURS PERSONNALISÉ','Bonjour, prêt à parler français ?','Chaque conversation vous rapproche d’une expression plus naturelle et plus assurée.')}
<section class="hero"><div class="hero-content"><div class="eyebrow" style="color:#c4b6ef">✦ Votre séance du jour · Jour ${d}</div><h1>Faites entendre<br/><em>votre voix.</em></h1><p>${esc(t.title)}<br/>7 min de cartes · 15 min de conversation · 5 min de bilan · 3 min de leçon.</p><div class="btn-row">${linkBtn(`#/cartes/${d}`,'Commencer ma séance  →','light')}${data.active?linkBtn(`#/studio/${data.active.day}/${data.active.mode}`,'Reprendre','ghost') : ''}</div></div><div class="hero-illustration" aria-hidden="true"><div class="orbit"><span>🎙️</span></div></div></section>
<div class="stat-grid"><div class="card pad stat"><span class="stat-icon">◷</span><div class="big">${data.sessions.length}</div><div class="label">Séances réalisées</div></div><div class="card pad stat"><span class="stat-icon">◈</span><div class="big">${known}</div><div class="label">Expressions maîtrisées</div></div><div class="card pad stat"><span class="stat-icon">✦</span><div class="big">${calcStreak()}</div><div class="label">Jours consécutifs</div></div></div>
<div class="grid-2"><section class="card pad"><div class="row between" style="margin-bottom:15px"><h2 style="margin:0;font-size:24px">Votre parcours</h2><a class="link" href="#/parcours">Voir les 30 jours →</a></div><div class="roadmap-mini">${topics.map(t=>`<a href="#/jour/${t.day}" class="day-dot ${done.has(t.day)?'done':t.day===d?'current':''}" title="Jour ${t.day} : ${esc(t.theme)}">${done.has(t.day)?'✓':t.day}</a>`).join('')}</div><p style="font-size:12px;margin:15px 0 0">${done.size} sur 30 sujets travaillés · Progression personnalisée</p></section><section class="focus-box"><div class="eyebrow">Votre point de départ</div><h2 style="font:normal 31px 'Instrument Serif',Georgia,serif">Un B1 à consolider,<br/>un B2 à construire.</h2><p>Votre diagnostic a mis en évidence trois priorités : conjuguer avec plus de précision, structurer vos arguments et enrichir vos expressions.</p><div class="spacer"></div>${linkBtn('#/mes-erreurs','Revoir mon diagnostic','dark')}</section></div>
<div class="section-title"><h2>À explorer cette semaine</h2><a class="link" href="#/parcours">Tous les sujets →</a></div><div class="topic-grid">${topics.slice(Math.max(0,d-1),Math.min(30,d+2)).map(dayCard).join('')}</div>`}
function parcours(){return `${title('30 JOURS · 4 ÉTAPES','Le parcours B1 → B2','Choisissez n’importe quel sujet. La difficulté progresse au fil des semaines.',`<span class="tag green">${doneDays().size} / 30 sujets</span>`)}${weekly.map((w,i)=>{const subset=topics.filter((t)=>i<3?t.day>=i*7+1&&t.day<=i*7+7:t.day>=22);return `<div class="week-head"><span class="tag">SEMAINE ${i+1} · ${w.level}</span><h2>${w.title}</h2></div><p style="font-size:13px">${w.note}</p><div class="topic-grid">${subset.map(dayCard).join('')}</div>`}).join('')}`}
function jour(day){const t=getTopic(day);return `<div class="study-container"><div class="breadcrumb"><a href="#/parcours">Parcours</a> / Semaine ${t.week} / Jour ${day}</div>${title(`JOUR ${day} · ${esc(t.theme)}`,esc(t.title),'Une séance complète de 30 minutes pour prendre confiance à l’oral.',`<span class="tag">${weekly[t.week-1].level}</span>`)}<div class="card pad" style="margin-bottom:17px"><div class="eyebrow">LE SUJET À DÉBATTRE</div><h2 style="font:normal 32px 'Instrument Serif',Georgia,serif;margin:13px 0">${esc(t.title)}</h2><p>${esc(t.prompt)}</p><div class="notice info">🎯 <b>Objectif :</b> ${esc(t.objective)}</div></div><div class="grid-3" style="margin:20px 0"><div class="card pad-sm"><div style="font-size:26px">🗂️</div><b>7 min</b><p style="font-size:12px;margin:4px 0">Flashcards et exemples</p></div><div class="card pad-sm"><div style="font-size:26px">🎙️</div><b>15 min</b><p style="font-size:12px;margin:4px 0">Discussion guidée</p></div><div class="card pad-sm"><div style="font-size:26px">📘</div><b>8 min</b><p style="font-size:12px;margin:4px 0">Bilan et mini-leçon</p></div></div>${linkBtn(`#/cartes/${day}`,'Commencer par les flashcards →','primary','block') }<div class="spacer"></div><div class="row wrap">${btn('start-session','🎤 Aller directement à la conversation','ghost',`data-day="${day}" data-mode="guide"`)}${btn('start-session','🕒 Examen blanc','ghost',`data-day="${day}" data-mode="examen"`)}</div></div>`}
function flashcards(day){const t=getTopic(day),cards=deck(day),i=Math.max(0,Math.min(ui.cardIndex,cards.length-1)),c=cards[i],review=data.reviews[c.id],progress=ui.cardDone?100:Math.round(100*i/cards.length);return `<div class="study-container"><div class="breadcrumb"><a href="#/jour/${day}">Jour ${day}</a> / Cartes de vocabulaire</div>${title('ÉTAPE 1 SUR 4','Les mots pour convaincre',`Sujet : ${esc(t.theme)} · ${cards.length} expressions utiles au niveau B2`)}${nextStage('cartes')}<div class="flash-layout"><div><div class="row between"><span class="eyebrow">CARTE ${ui.cardDone?cards.length:i+1} SUR ${cards.length}</span><span class="tag ${review?.rating==='known'?'green':'neutral'}">${review?.rating==='known'?'✓ Déjà connue':'Répétition active'}</span></div><div class="card-progress"><div style="width:${progress}%"></div></div>${ui.cardDone?`<div class="card pad" style="text-align:center;min-height:300px;display:grid;place-content:center;gap:12px"><div style="font-size:54px">✦</div><h2>Cartes terminées !</h2><p>Vous êtes prêt à utiliser ces expressions dans une conversation réelle.</p>${btn('start-session','Commencer la conversation →','primary',`data-day="${day}" data-mode="guide"`)}</div>`:`<div class="flashcard ${ui.flipped?'flipped':''}" data-action="flip" role="button" tabindex="0" aria-label="Retourner la carte"><div class="flash-inner"><div class="flash-face front"><div class="eyebrow">EXPRESSION DU JOUR</div><h2>${esc(c.term)}</h2><div class="hint">Touchez pour voir le sens et un exemple ↗</div></div><div class="flash-face back"><div class="eyebrow" style="color:#cbbaf3">DÉFINITION</div><div class="definition">${esc(c.definition)}</div><div class="example">« ${esc(c.example)} »</div><div class="hint">Touchez pour retourner la carte</div></div></div></div><div class="button-center">${btn('speak-card','🔊 Écouter','ghost')}${btn('grade-card','À revoir','soft','data-grade="missed"')}${btn('grade-card','✓ Je connais','success','data-grade="known"')}</div>`}</div><aside class="card flash-side"><div class="eyebrow">CONSEIL DE CAMILLE</div><h3>Ne mémorisez pas seulement le mot.</h3><p style="font-size:13px">Imaginez une phrase que vous pourriez dire pendant un examen.</p><ul><li>Prononcez chaque expression à haute voix.</li><li>Associez-la à un argument ou à un exemple.</li><li>Retrouvez plus tard les cartes difficiles dans « Mes erreurs ».</li></ul></aside></div></div>`}
function studioLanding(){const t=getTopic(currentDay());return `${title('UN ESPACE POUR PARLER','Studio oral','Trois façons de vous entraîner, de B1+ jusqu’aux conditions de l’examen.')}${data.active?`<div class="notice info" style="margin-bottom:18px">Une séance est en cours : <a href="#/studio/${data.active.day}/${data.active.mode}"><b>Reprendre le sujet « ${esc(getTopic(data.active.day).theme)} » →</b></a></div>`:''}<div class="mode-grid"><div class="card mode-card"><span class="feature-icon">🎙️</span><h3>Conversation guidée</h3><p>Discutez avec Camille. Vos réponses s’affichent à l’écran et les corrections arrivent à la fin.</p>${btn('start-session','Commencer · 15 min →','primary',`data-day="${t.day}" data-mode="guide"`)}</div><div class="card mode-card"><span class="feature-icon">🗣️</span><h3>Monologue argumenté</h3><p>Présentez un problème et défendez votre point de vue pendant 5 à 7 minutes.</p>${btn('start-session','M’entraîner →','soft',`data-day="${t.day}" data-mode="monologue"`)}</div><div class="card mode-card"><span class="feature-icon">🏅</span><h3>Examen blanc</h3><p>30 minutes de préparation, 5 à 7 minutes d’exposé, puis 10 à 13 minutes de débat.</p>${btn('start-session','Simuler l’épreuve →','dark',`data-day="${t.day}" data-mode="examen"`)}</div></div><div class="section-title"><h2>Choisissez votre sujet</h2><a class="link" href="#/parcours">Tous les thèmes →</a></div><div class="topic-grid">${topics.slice(0,6).map(dayCard).join('')}</div>`}
function startSession(day,mode='guide'){day=Number(day);const t=getTopic(day);if(data.active && (data.active.day!==day||data.active.mode!==mode)){if(!confirm('Une séance est déjà en cours. Voulez-vous la remplacer ? La conversation non terminée sera perdue.'))return false}
 if(!data.active || data.active.day!==day || data.active.mode!==mode){data.active={id:uid(),day,mode,startedAt:new Date().toISOString(),phase:mode==='examen'?'preparation':mode==='monologue'?'monologue':'debat',phaseStartedAt:Date.now(),pausedAt:null,pausedTotalMs:0,messages:mode==='guide'?[{role:'examiner',text:`${t.prompt}\n\nQuel est votre point de vue ?`,phase:'debat'}]:[],round:0,aiUsed:false};save()}
 ui.draft='';ui.viaMic=false;ui.asrUncertain=false;ui.showTextInExam=false;location.hash=`#/studio/${day}/${mode}`;render();if(mode==='guide'&&data.preferences.autoSpeak){const intro=data.active.messages.find(m=>m.role==='examiner');if(intro)speak(intro.text)}return true}
function phaseText(phase){return {preparation:'Préparation',monologue:'Monologue suivi',debat:'Débat avec l’examinatrice'}[phase]||'Conversation'}
function elapsed(a){if(!a)return 0;return Math.floor(((a.pausedAt||Date.now())-a.phaseStartedAt-(a.pausedTotalMs||0))/1000)}
function studioPage(day,mode){const a=data.active,t=getTopic(day);if(!a || a.day!==day || a.mode!==mode)return `<div class="study-container">${title('STUDIO ORAL','Une nouvelle conversation','Votre séance n’a pas encore commencé.')}<div class="card pad"><h2>${esc(t.title)}</h2><p>${esc(t.prompt)}</p>${btn('start-session','Démarrer maintenant','primary',`data-day="${day}" data-mode="${mode}"`)}</div></div>`;
const exam=a.mode==='examen',prep=exam&&a.phase==='preparation',monologue=a.phase==='monologue',hideText=exam && !ui.showTextInExam;
const status=ui.aiAvailable?'Camille · IA adaptative':'Camille · questions préétablies';
const msgs=a.messages.map(m=>{if(exam&&m.role==='learner')return `<div class="speech-hidden">✓ Réponse orale enregistrée · transcription masquée jusqu’au bilan</div>`;return `<div class="chat ${m.role==='examiner'?'examiner':'learner'}"><div class="sender">${m.role==='examiner'?'◉ Camille':'Vous'}${m.phase==='monologue'?' · Monologue':''}</div>${esc(m.text)}</div>`}).join('');
const goal=prep?'30:00':a.phase==='monologue'?'05:00–07:00':exam?'10:00–13:00':'15:00';
return `<div class="breadcrumb"><a href="#/jour/${day}">Jour ${day}</a> / ${esc(mode==='guide'?'Conversation guidée':mode==='monologue'?'Monologue argumenté':'Examen blanc')}</div><div class="page-heading"><div><div class="eyebrow">ÉTAPE 2 SUR 4 · ${exam?'EXAMEN BLANC':'ENTRAÎNEMENT ORAL'}</div><h1>Votre voix compte.</h1><p>${esc(t.title)}</p></div><span class="mode-label ${ui.aiAvailable?'':'offline'}">${ui.aiAvailable?'✦ IA disponible':'◉ Mode hors ligne · questions préétablies'}</span></div>${nextStage('studio')}
${exam?`<div class="phase-steps" style="margin-bottom:15px">${['preparation','monologue','debat'].map((phase,i)=>`<div class="step ${a.phase===phase?'active':['preparation','monologue','debat'].indexOf(a.phase)>i?'done':''}">${['1. Préparation','2. Monologue','3. Débat'][i]}</div>`).join('')}</div>`:''}
<div class="studio"><section><div class="card pad" style="margin-bottom:14px"><div class="row between wrap"><div><div class="eyebrow">${esc(phaseText(a.phase))}</div><h2 style="margin:6px 0 0;font-size:22px">${esc(t.theme)}</h2></div><div class="row">${btn('speak-last','🔊 Écouter','ghost small',prep?'disabled':'')}${btn('end-session','Terminer','danger small',`data-mode="${mode}"`)}</div></div></div>
${prep?`<div class="card pad"><div class="eyebrow">VOTRE DOCUMENT DÉCLENCHEUR</div><h2 style="font:normal 34px 'Instrument Serif',Georgia,serif;margin:13px 0">${esc(t.title)}</h2><p>${esc(t.prompt)}</p><div class="notice info">Préparez une problématique, deux ou trois arguments, des exemples et une conclusion. Vous pouvez prendre des notes sur papier.</div><div class="spacer"></div>${btn('next-phase','Commencer mon monologue →','primary')}</div>`:
`<div class="chat-panel" id="chat-panel" aria-label="Conversation avec l’examinatrice">${msgs||`<div class="chat examiner"><div class="sender">Sujet à présenter</div>${esc(t.prompt)}<br/><b>Présentez votre point de vue de manière structurée.</b></div>`}${ui.waiting?'<div class="chat examiner">Camille prépare la question suivante…</div>':''}</div>
<div class="card pad transcript-box"><div class="row between"><div><b>${monologue?'Votre présentation':exam?'Votre réponse (masquée pendant l’épreuve)':'Votre réponse'}</b><div class="micro-note">${hideText?'La transcription sera visible après le bilan.':'Parlez puis vérifiez votre transcription avant de l’envoyer.'}</div></div>${ui.listening?'<span class="tag peach">● Écoute en cours</span>':'<span class="tag neutral">fr-FR</span>'}</div>
<div style="margin-top:12px">${hideText?`<div class="speech-hidden">🎙️ Transcription masquée · ${ui.draft.trim()?`${ui.draft.trim().split(/\s+/).length} mots enregistrés`:'Aucune réponse enregistrée'}.<br/>Si votre micro n’est pas compatible, utilisez « Saisie manuelle ».</div>`:''}<textarea id="draft-input" class="textarea" aria-label="Votre réponse en français" placeholder="Je pense que…" style="${hideText?'display:none':''}">${esc(ui.draft)}</textarea><div id="interim" class="micro-note" aria-live="polite">${esc(ui.interim)}</div></div>
<div class="talk-controls"><button type="button" class="mic-button ${ui.listening?'listening':''}" data-action="toggle-mic" id="mic-control" aria-label="${ui.listening?'Arrêter le micro':'Activer le micro'}">${ui.listening?'■':'🎙'}</button><span class="micro-note" id="mic-status">${ui.listening?'Je vous écoute…':'Appuyez pour parler.'}</span><div style="flex:1"></div>${hideText?btn('toggle-exam-text','Saisie manuelle','ghost small'):''}${btn('send-answer','Envoyer →','primary',ui.waiting?'disabled':'')}</div>
${!ui.aiAvailable?`<div class="notice info" style="margin-top:13px">Sans clé d’API configurée, Camille utilise des questions préétablies. L’analyse grammaticale locale sera limitée aux erreurs reconnues dans vos phrases.</div>`:''}
</div>`}
</section><aside class="study-aside"><div class="card pad-sm"><div class="eyebrow">CHRONOMÈTRE</div><div class="timer-block" data-elapsed>${fmtTime(elapsed(a))}</div><div class="muted" style="font-size:12px">Objectif : ${goal}</div><div class="divider"></div><div class="row wrap">${btn('toggle-pause',a.pausedAt?'▶ Reprendre':'Ⅱ Pause','ghost small')}${btn('reset-timer','↻ Réinitialiser','ghost small')}</div></div><div class="card pad-sm"><div class="eyebrow">CONSEILS</div><h3>${exam?'Conditions de l’épreuve':'Parlez sans chercher la perfection.'}</h3><p style="font-size:13px">${exam?'Pendant l’examen blanc, les corrections et la transcription sont conservées pour le bilan final.':'N’ayez pas peur des erreurs. Camille vous écoute ; l’analyse n’intervient qu’à la fin.'}</p><div class="row between"><span style="font-size:12px">Réponses enregistrées</span><b>${a.messages.filter(m=>m.role==='learner').length}</b></div>${exam&&a.phase==='monologue'?`<div style="margin-top:13px">${btn('next-phase','Passer au débat →','dark block')}</div>`:''}</div>${mode==='guide'?`<div class="focus-box"><div class="eyebrow">OBJECTIF DU JOUR</div><p>${esc(t.objective)}</p></div>`:''}</aside></div>`}
function metrics(messages){const answers=messages.filter(m=>m.role==='learner').map(m=>m.text);const all=answers.join(' ');const words=all.trim()?all.trim().split(/\s+/).length:0;const connectives=['par exemple','à mon avis','néanmoins','cependant','en revanche','tout d’abord','en définitive','selon moi','par conséquent','en effet','en outre','dans la mesure où','bien que','d’une part','d’autre part','pour conclure','à cause de','grâce à','même si'];return {responses:answers.length,words,avgWords:answers.length?Math.round(words/answers.length):0,connectors:connectives.filter(c=>all.toLowerCase().includes(c)),longestAnswer:Math.max(0,...answers.map(a=>a.trim().split(/\s+/).length))}}
const localPatterns=[
 {re:/\bde mon avis\b/ig,right:'à mon avis',category:'Expression',explain:'Pour introduire une opinion personnelle, on emploie « à mon avis ».'},
 {re:/\ble solitude\b/ig,right:'la solitude',category:'Accord',explain:'« Solitude » est un nom féminin.'},
 {re:/\bj['’]ai souffré\b/ig,right:'j’ai souffert',category:'Conjugaison',explain:'Le participe passé du verbe « souffrir » est « souffert ».'},
 {re:/\bplusieurs de temps\b/ig,right:'beaucoup de temps',category:'Lexique',explain:'Pour une quantité indénombrable, on dit « beaucoup de temps ».'},
 {re:/\bl['’]apprendre\b/ig,right:'l’apprentissage',category:'Lexique',explain:'Après « faciliter », le nom naturel est « l’apprentissage ».'},
 {re:/\bje mémorise que\b/ig,right:'je me souviens que',category:'Lexique',explain:'Pour parler d’un souvenir, « je me souviens que » est plus naturel.'},
 {re:/\b(?:en|dans) Youtube\b/ig,right:'sur YouTube',category:'Préposition',explain:'On dit regarder des vidéos « sur YouTube ».'},
 {re:/\bdes plusieurs domaines\b/ig,right:'plusieurs domaines',category:'Grammaire',explain:'« Plusieurs » se place directement devant le nom sans « des ».'},
 {re:/\bpermet moi de\b/ig,right:'me permet de',category:'Grammaire',explain:'Le pronom complément se place avant le verbe conjugué : « me permet ».'}
];
function localFeedback(messages){const text=messages.filter(m=>m.role==='learner').map(m=>m.text).join(' ');const errors=[];for(const p of localPatterns){p.re.lastIndex=0;const match=p.re.exec(text);if(match)errors.push({quote:match[0],correction:p.right,category:p.category,explanation:p.explain,asrUncertain:false})}return {kind:'local',summary:'Bilan descriptif limité : ces indicateurs sont mesurés directement dans votre transcription. Il ne s’agit pas d’une évaluation complète du niveau B2.',strengths:[],errors,priorities:errors.length?errors.slice(0,3).map(e=>e.explanation):['Développer un argument avec un exemple précis.','Ajouter une concession ou une objection.','Réutiliser les expressions révisées.'],criteria:null}}
async function askExaminer(a,t){const learners=a.messages.filter(m=>m.role==='learner');if(learners.length>=7)return;let question=t.questions[Math.max(0,learners.length-1)%t.questions.length];if(ui.aiAvailable){try{const r=await fetch('/api/examiner',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:{title:t.title,prompt:t.prompt,objective:t.objective},messages:a.messages,mode:a.mode,phase:a.phase})});if(!r.ok)throw new Error();const d=await r.json();if(d.question&&typeof d.question==='string'){question=d.question;a.aiUsed=true}}catch{toast('IA indisponible : passage aux questions préétablies.')}}a.messages.push({role:'examiner',text:question,phase:a.phase});save()}
async function finishSession(){const a=data.active;if(!a)return;stopMic();const learner=a.messages.filter(m=>m.role==='learner');if(!learner.length){toast('Enregistrez au moins une réponse avant le bilan.');return}ui.waiting=true;render();const t=getTopic(a.day),record={id:a.id,day:a.day,mode:a.mode,topicTitle:t.title,startedAt:a.startedAt,endedAt:new Date().toISOString(),messages:a.messages,aiUsed:a.aiUsed,metrics:metrics(a.messages),feedback:null,lessonId:null};let feedback=localFeedback(a.messages);if(ui.aiAvailable){try{const r=await fetch('/api/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:{title:t.title,objective:t.objective},mode:a.mode,messages:a.messages})});if(!r.ok)throw new Error('API indisponible');const v=await r.json();if(v&&v.kind==='ai'&&Array.isArray(v.errors)&&v.criteria)feedback=v;else throw new Error('Réponse non valide')}catch{toast('Analyse IA indisponible. Bilan local limité affiché.')}}record.feedback=feedback;
if(feedback.kind==='ai'&&feedback.lesson&&feedback.errors?.length){const l={...feedback.lesson,id:uid(),source:'session',sessionId:record.id,createdAt:record.endedAt};data.lessons.unshift(l);record.lessonId=l.id}
else if(feedback.kind==='local'&&feedback.errors.length){const err=feedback.errors[0];const diag=diagnostic.find(d=>d.wrong.toLowerCase()===err.quote.toLowerCase()||d.category.toLowerCase()===err.category.toLowerCase());if(diag){const l={...diag,id:uid(),source:'session',sessionId:record.id,createdAt:record.endedAt};data.lessons.unshift(l);record.lessonId=l.id}}
data.sessions.unshift(record);data.active=null;ui.waiting=false;ui.draft='';save();location.hash=`#/bilan/${record.id}`;render()}
async function sendAnswer(){const a=data.active;if(!a||ui.waiting)return;stopMic();let val=(ui.draft||$('#draft-input')?.value||'').trim();if(!val){toast('Parlez ou écrivez d’abord une réponse en français.');return}if(val.length>5000){toast('Votre réponse est trop longue pour être traitée en une fois.');return}a.messages.push({role:'learner',text:val,viaMic:ui.viaMic,asrUncertain:ui.asrUncertain,phase:a.phase});a.round++;ui.draft='';ui.asrUncertain=false;ui.viaMic=false;save();render();if(a.phase==='debat'&&a.round<7){ui.waiting=true;render();await askExaminer(a,getTopic(a.day));ui.waiting=false;render();if(data.preferences.autoSpeak&&a.messages.at(-1).role==='examiner')speak(a.messages.at(-1).text)}else{toast('Réponse enregistrée. Vous pouvez terminer la séance et consulter le bilan.')}}
function changePhase(){const a=data.active;if(!a||a.mode!=='examen')return;stopMic();if(ui.draft.trim()){if(!confirm('Une réponse n’a pas été envoyée. Passer à l’étape suivante sans l’enregistrer ?'))return;ui.draft=''}if(a.phase==='preparation'){a.phase='monologue'}else if(a.phase==='monologue'){if(!a.messages.some(m=>m.role==='learner')){toast('Présentez votre monologue avant de passer au débat.');return}a.phase='debat';a.messages.push({role:'examiner',text:getTopic(a.day).questions[0],phase:'debat'})}a.phaseStartedAt=Date.now();a.pausedTotalMs=0;a.pausedAt=null;ui.showTextInExam=false;save();render()}
function speak(text){if(!('speechSynthesis' in window)){toast('La lecture vocale n’est pas disponible sur ce navigateur.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='fr-FR';u.rate=data.preferences.rate;const voices=speechSynthesis.getVoices(),v=voices.find(v=>v.lang==='fr-FR')||voices.find(v=>v.lang.startsWith('fr'));if(v)u.voice=v;speechSynthesis.speak(u)}
function stopMic(){if(ui.recognition){try{ui.recognition.stop()}catch{}ui.recognition=null}ui.listening=false;updateMicUI()}
function updateMicUI(){const b=$('#mic-control'),s=$('#mic-status'),i=$('#interim');if(b){b.classList.toggle('listening',ui.listening);b.textContent=ui.listening?'■':'🎙';b.setAttribute('aria-label',ui.listening?'Arrêter le micro':'Activer le micro')}if(s)s.textContent=ui.listening?'Je vous écoute…':'Appuyez pour parler.';if(i)i.textContent=ui.interim}
function toggleMic(){if(ui.listening){stopMic();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Votre navigateur ne propose pas la dictée vocale. Utilisez le champ de texte.');if(data.active?.mode==='examen'){ui.showTextInExam=true;render()}return}window.speechSynthesis?.cancel();try{const rec=new SR();ui.recognition=rec;rec.lang='fr-FR';rec.continuous=true;rec.interimResults=true;rec.maxAlternatives=1;rec.onstart=()=>{ui.listening=true;updateMicUI()};rec.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){let r=e.results[i];if(r.isFinal){ui.draft=(ui.draft+' '+r[0].transcript).trim();ui.viaMic=true;if(r[0].confidence>0&&r[0].confidence<0.6)ui.asrUncertain=true;const el=$('#draft-input');if(el)el.value=ui.draft}else ui.interim=r[0].transcript}updateMicUI();const out=$('.speech-hidden');if(out&&data.active?.mode==='examen')out.textContent='🎙️ Réponse en cours · transcription masquée jusqu’au bilan.'};rec.onerror=e=>{ui.listening=false;const err={'not-allowed':'Autorisation du microphone refusée. Vérifiez les réglages de votre navigateur.','service-not-allowed':'Service vocal non autorisé. Utilisez le clavier.','no-speech':'Aucune parole détectée. Réessayez.','network':'Une connexion est nécessaire pour la reconnaissance vocale.','audio-capture':'Impossible d’accéder au microphone.'};toast(err[e.error]||`Erreur du microphone : ${e.error}`);updateMicUI()};rec.onend=()=>{ui.listening=false;ui.recognition=null;ui.interim='';updateMicUI()};rec.start()}catch{toast('Impossible de démarrer le microphone. Utilisez le clavier.')}}
function bilan(id){const s=data.sessions.find(s=>s.id===id);if(!s)return `<div class="empty card"><h2>Ce bilan est introuvable.</h2>${linkBtn('#/progres','Voir mes progrès')}</div>`;const f=s.feedback||localFeedback(s.messages),m=s.metrics;const scores=f.kind==='ai'?f.criteria:null;const scoreEntries=scores?Object.entries(scores):[];const total=scoreEntries.length===5 && scoreEntries.every(([,v])=>Number.isFinite(v.score))?scoreEntries.reduce((n,[,v])=>n+v.score,0):null;const partial=scoreEntries.filter(([,v])=>Number.isFinite(v.score));const partialTotal=partial.reduce((n,[,v])=>n+v.score,0);const labels={monologue:'Monologue suivi',interaction:'Exercice en interaction',lexique:'Lexique',morphosyntaxe:'Morphosyntaxe',phonologie:'Système phonologique'};
return `<div class="study-container"><div class="breadcrumb"><a href="#/progres">Mes progrès</a> / ${esc(fmt(s.endedAt))}</div>${title('ÉTAPE 3 SUR 4','Votre bilan personnalisé',`${esc(s.topicTitle)} · ${esc(fmt(s.endedAt))}`,`<span class="tag ${f.kind==='ai'?'green':'peach'}">${f.kind==='ai'?'Analyse IA':'Analyse locale limitée'}</span>`)}${nextStage('bilan')}
<div class="card pad" style="margin-bottom:17px"><div class="eyebrow">VOTRE SÉANCE EN CHIFFRES</div><div class="stat-grid" style="margin-bottom:0"><div class="stat"><div class="big">${m.responses}</div><div class="label">Prises de parole</div></div><div class="stat"><div class="big">${m.words}</div><div class="label">Mots transcrits</div></div><div class="stat"><div class="big">${m.connectors.length}</div><div class="label">Connecteurs repérés</div></div></div><p style="font-size:13px;margin:14px 0 0">${esc(f.summary)}</p></div>
<div class="card pad" style="margin-bottom:17px"><div class="row between wrap"><h2 style="margin:0">Évaluation DELF B2</h2><span class="tag neutral">Estimation pédagogique</span></div>${!scores?`<div class="notice info" style="margin-top:14px">Le mode local ne permet pas d’évaluer de façon fiable vos compétences B2. Connectez un service IA pour obtenir une analyse des critères linguistiques et de vos arguments.</div>`:`<div class="summary-criteria" style="margin-top:18px">${scoreEntries.map(([k,v])=>`<div class="score-cell"><h4>${labels[k]||k}</h4><div class="score">${Number.isFinite(v.score)?`${v.score}<span style="font-size:16px;color:var(--muted)">/5</span>`:'—'}</div><p>${esc(v.comment||'Non évalué')}</p></div>`).join('')}</div><p style="font-size:12px;margin-top:13px">${total!==null?`Score indicatif : ${total}/25`:`Score partiel des critères évaluables : ${partialTotal}/${partial.length*5}. Les autres critères sont non évalués ; aucun total /25 ne peut être calculé.`} L’appréciation ne remplace pas l’évaluation d’un jury officiel.</p>`}<div class="notice info" style="margin-top:14px">La prononciation, l’intonation et le rythme ne peuvent pas être jugés à partir de la seule transcription. Les erreurs de dictée peuvent aussi fausser certaines formulations.</div></div>
<div class="card pad" style="margin-bottom:17px"><h2>Vos corrections</h2>${f.errors?.length?f.errors.map(e=>`<div class="err-card"><div class="row between"><span class="tag peach">${esc(e.category)}</span>${e.asrUncertain?'<span class="muted" style="font-size:11px">Transcription à vérifier</span>':''}</div><p class="wrong" style="margin:12px 0 6px">« ${esc(e.quote)} »</p><p class="correct" style="margin-bottom:7px">✓ ${esc(e.correction)}</p><p style="font-size:13px;margin-bottom:0">${esc(e.explanation)}</p></div>`).join(''):`<div class="notice info" style="margin-top:15px">${f.kind==='local'?'Aucune erreur correspondant aux règles locales n’a été détectée. Cela ne signifie pas que votre français est sans erreur ; une évaluation IA permettrait un examen plus complet.':'Aucune erreur significative relevée dans cet échange.'}</div>`}<h3 style="margin-top:22px">Trois priorités de progression</h3><ol class="list-dots">${(f.priorities||[]).slice(0,3).map(p=>`<li>${esc(p)}</li>`).join('')}</ol></div>
<div class="card pad" style="margin-bottom:17px"><h2>Votre transcription</h2><p style="font-size:12px">Relisez vos réponses après la conversation. Si une phrase contient une erreur de reconnaissance vocale, ne la considérez pas automatiquement comme une erreur de français.</p><div class="stack">${s.messages.map(m=>`<div class="chat ${m.role==='examiner'?'examiner':'learner'}" style="max-width:100%"><div class="sender">${m.role==='examiner'?'Camille':'Vous'} ${m.asrUncertain?'· dictée incertaine':''}</div>${esc(m.text)}</div>`).join('')}</div></div>
<div class="sticky-actions">${s.lessonId?linkBtn(`#/lecon/${s.lessonId}`,'Ma leçon personnalisée →','primary'):linkBtn('#/mes-erreurs','Revoir mes points faibles →','primary')}${linkBtn('#/parcours','Changer de sujet','ghost')}</div></div>`}
function findLesson(id){return data.lessons.find(l=>l.id===id)||diagnostic.find(l=>l.id===id)}
function normalizedExercises(l){if(Array.isArray(l.exercises)&&l.exercises.length)return l.exercises.map(e=>({prompt:e.prompt,options:e.options?.length?e.options:[e.answer,'—','Autre'],answer:e.answer,hint:e.hint}));if(l.question)return[{prompt:l.question,options:l.options,answer:l.answer}];return[]}
function lecon(id){const l=findLesson(id);if(!l)return `<div class="card pad empty"><h2>Leçon introuvable</h2>${linkBtn('#/mes-erreurs','Retour aux leçons')}</div>`;const ex=normalizedExercises(l),idx=Math.min(ui.exerciseIndex,Math.max(0,ex.length-1)),q=ex[idx];return `<div class="study-container"><div class="breadcrumb"><a href="#/mes-erreurs">Mes erreurs</a> / Leçon</div>${title('ÉTAPE 4 SUR 4','Apprendre de mes erreurs',esc(l.title),`<span class="tag ${l.source==='diagnostic'?'neutral':'green'}">${l.source==='diagnostic'||!l.source?'Votre diagnostic B1':'Votre séance'}</span>`)}${nextStage('lecon')}
<div class="card pad" style="margin-bottom:17px"><div class="eyebrow">LA RÈGLE EN FRANÇAIS</div><h2 style="margin-top:10px">${esc(l.title)}</h2><div class="lesson-rule">${esc(l.rule)}</div>${l.wrong&&l.right?`<div class="grid-2" style="margin-top:18px"><div class="notice" style="background:#fff4f2;color:#a34c48;border-color:#f3dcd9"><b>À éviter :</b><br/>${esc(l.wrong)}</div><div class="notice success"><b>À retenir :</b><br/>${esc(l.right)}</div></div>`:''}${Array.isArray(l.examples)?l.examples.map(e=>`<div class="err-card"><p class="wrong">${esc(e.wrong)}</p><p class="correct">✓ ${esc(e.right)}</p></div>`).join(''):''}</div>
<div class="card pad" style="margin-bottom:17px"><div class="row between"><h2 style="margin:0">À vous de jouer</h2><span class="tag">Exercice ${ex.length?idx+1:0}/${ex.length}</span></div>${q?`<p style="margin-top:15px;font-weight:600">${esc(q.prompt)}</p><div class="exercise-options">${q.options.map((opt,j)=>`<button class="choice ${ui.lessonChoice===opt?'active':''}" data-action="lesson-choice" data-value="${esc(opt)}">${esc(opt)}</button>`).join('')}</div>${btn('verify-choice','Vérifier ma réponse','primary',ui.lessonChoice===null?'disabled':'')}${ui.checked?`<div class="exercise-answer" style="margin-top:13px">${ui.lessonChoice===q.answer?'✓ Bravo !':'Réponse attendue : '+esc(q.answer)} ${q.hint?esc(q.hint):''}</div>${idx<ex.length-1?btn('next-exercise','Exercice suivant →','ghost',`style="margin-top:12px"`):''}`:''}`:`<p>Relisez la règle et réutilisez-la dans un nouvel exemple personnel.</p>`}</div>
<div class="card pad"><div class="eyebrow">RÉESSAYER À L’ORAL</div><h2 style="margin-top:9px">Utilisez la règle dans une vraie phrase.</h2><p>${esc(l.retryPrompt||'Reformulez votre idée en utilisant la correction.')}</p><textarea id="retry-text" class="textarea" aria-label="Votre nouvelle réponse" placeholder="Ma nouvelle phrase en français…">${esc(ui.answerDraft)}</textarea><div class="btn-row" style="margin-top:13px">${btn('retry-mic','🎙️ Dictée','ghost')}${btn('save-retry','Enregistrer ma nouvelle phrase','primary',`data-id="${esc(id)}"`)}</div><p style="font-size:12px;margin-top:11px">Votre phrase sera enregistrée comme pratique ; la correction automatique n’est pas garantie.</p></div></div>`}
