function reviewPage(){const seen=new Map(topics.flatMap(t=>deck(t.day)).map(c=>[c.id,c]));if(!ui.reviewQueue)ui.reviewQueue=Object.entries(data.reviews).filter(([,v])=>v.rating==='missed').map(([id])=>id);const cards=ui.reviewQueue.map(id=>seen.get(id)).filter(Boolean);if(!cards.length)return `<div class="study-container">${title('RÉPÉTITION','Mes cartes difficiles','Toutes vos expressions à réviser.') }<div class="card pad empty"><h2>Plus de cartes difficiles !</h2>${linkBtn('#/parcours','Choisir un sujet →')}</div></div>`;const i=Math.min(ui.cardIndex,cards.length-1),c=cards[i];return `<div class="study-container">${title('RÉPÉTITION','Mes cartes difficiles',`${cards.length} expressions à renforcer.`)}<div class="flash-layout"><div>${ui.cardDone?`<div class="card pad empty"><h2>Révision terminée</h2>${linkBtn('#/mes-erreurs','Revenir au carnet')}</div>`:`<div class="row between"><span class="eyebrow">CARTE ${i+1}/${cards.length}</span></div><div class="flashcard ${ui.flipped?'flipped':''}" data-action="flip"><div class="flash-inner"><div class="flash-face"><h2>${esc(c.term)}</h2><div class="hint">Touchez pour révéler le sens</div></div><div class="flash-face back"><div class="definition">${esc(c.definition)}</div><div class="example">${esc(c.example)}</div></div></div></div><div class="button-center">${btn('speak-review','🔊 Écouter','ghost')}${btn('grade-review','Encore','soft','data-grade="missed"')}${btn('grade-review','✓ Je connais','success','data-grade="known"')}</div>`}</div><aside class="card flash-side"><h3>Répéter, c’est progresser.</h3><p>Prononcez l’expression puis utilisez-la dans une phrase personnelle.</p></aside></div></div>`}
function progress(){const sessions=data.sessions,known=Object.values(data.reviews).filter(r=>r.rating==='known').length,byDate={};sessions.forEach(s=>{const k=new Date(s.endedAt).toLocaleDateString('en-CA');byDate[k]=(byDate[k]||0)+1});const last=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()-13+i);return byDate[d.toLocaleDateString('en-CA')]||0});const max=Math.max(1,...last);return `${title('SUIVI DES EFFORTS','Mes progrès','Votre progression réelle, séance après séance, sans statistiques inventées.')}
<div class="stat-grid"><div class="card pad stat"><div class="stat-icon">✦</div><div class="big">${sessions.length}</div><div class="label">Séances terminées</div></div><div class="card pad stat"><div class="stat-icon">🔥</div><div class="big">${calcStreak()}</div><div class="label">Jours consécutifs</div></div><div class="card pad stat"><div class="stat-icon">✎</div><div class="big">${known}</div><div class="label">Expressions maîtrisées</div></div></div>
<div class="grid-2"><div class="card pad"><div class="eyebrow">LES QUATORZE DERNIERS JOURS</div><h2>Régularité des séances</h2><div class="mini-bars">${last.map(v=>`<span title="${v} séance(s)" style="height:${v?Math.max(12,v/max*100):3}%"></span>`).join('')}</div><div class="row between muted" style="font-size:11px"><span>Il y a 14 jours</span><span>Aujourd’hui</span></div></div><div class="card pad"><div class="eyebrow">OBJECTIF DE PRÉPARATION</div><h2>30 sujets pour progresser</h2><div class="row between"><span class="muted" style="font-size:13px">Sujets travaillés</span><b>${doneDays().size} / 30</b></div><div class="progress-large" style="margin:15px 0"><div style="width:${Math.round(doneDays().size/30*100)}%"></div></div><p style="font-size:12px">La pratique régulière est plus importante qu’une note ponctuelle.</p>${linkBtn('#/parcours','Explorer les sujets →','ghost')}</div></div>
<div class="section-title"><h2>Historique de mes conversations</h2></div><div class="card">${sessions.length?sessions.map(s=>`<a class="history-item" href="#/bilan/${s.id}"><div><b>${esc(s.topicTitle)}</b><div class="muted" style="font-size:12px">${esc(fmt(s.endedAt))} · ${s.mode==='guide'?'Conversation guidée':s.mode==='monologue'?'Monologue':'Examen blanc'} · ${s.metrics.words} mots</div></div><span style="font-size:20px;color:var(--violet)">↗</span></a>`).join(''):`<div class="empty"><div class="illustration">📖</div><h3>Votre histoire commence aujourd’hui.</h3><p>Les séances terminées apparaîtront ici avec leur transcription et leur bilan.</p>${linkBtn('#/studio','Prendre la parole →')}</div>`}</div>`}
function settings(){return `<div class="study-container">${title('VOTRE ESPACE','Paramètres','Préférences vocales, confidentialité et gestion des données.') }<div class="card pad stack"><h2>Voix de Camille</h2><label for="rate">Vitesse de lecture : <b id="rate-value">${Math.round(data.preferences.rate*100)} %</b></label><input id="rate" type="range" min="70" max="120" value="${Math.round(data.preferences.rate*100)}" style="width:100%;accent-color:var(--violet)"/><div class="row wrap">${btn('test-voice','🔊 Écouter une phrase','ghost')}<label class="row" style="font-size:13px"><input id="auto-speak" type="checkbox" ${data.preferences.autoSpeak?'checked':''}/> Lire automatiquement les nouvelles questions</label></div><div class="divider"></div><h2>Confidentialité</h2><p>Vos séances, transcriptions et révisions sont conservées dans ce navigateur (stockage local), sans compte et sans synchronisation automatique. Si vous activez l’IA avec une clé sur votre serveur, les textes envoyés au serveur sont transmis au fournisseur d’IA pour générer des questions et des corrections. Le microphone utilise les fonctions du navigateur, qui peuvent traiter la parole via un service externe selon votre appareil.</p><div class="btn-row">${btn('export','↓ Exporter mes données','ghost')}${btn('clear-all','Effacer mes données','danger')}</div><div class="divider"></div><h2>À propos du DELF B2</h2><p>Parole B2 est un outil indépendant de préparation. L’épreuve orale comprend 30 minutes de préparation, un monologue de 5 à 7 minutes et un débat de 10 à 13 minutes. Ce site ne délivre pas de note officielle.</p><a class="link" href="https://www.france-education-international.fr/document/grille-po-b2" target="_blank" rel="noopener">Consulter la grille officielle de production orale ↗</a></div></div>`}
function render(){const path=(location.hash||'#/accueil').replace(/^#\/?/,'');let parts=path.split('/'),route=parts[0]||'accueil';if(ui.route!==path){stopMic();ui.draft='';ui.interim='';ui.flipped=false;ui.cardIndex=0;ui.cardDone=false;ui.lessonChoice=null;ui.checked=false;ui.exerciseIndex=0;ui.answerDraft='';ui.showTextInExam=false;ui.reviewQueue=null;ui.route=path}let content;switch(route){case 'accueil':content=home();break;case 'parcours':content=parcours();break;case 'jour':content=jour(Number(parts[1])||1);break;case 'cartes':content=flashcards(Number(parts[1])||1);break;case 'studio':content=parts[1]?studioPage(Number(parts[1]),parts[2]||'guide'):studioLanding();break;case 'bilan':content=bilan(parts[1]);break;case 'lecon':content=lecon(parts[1]);break;case 'mes-erreurs':content=errorsPage();break;case 'revision':content=reviewPage();break;case 'progres':content=progress();break;case 'parametres':content=settings();break;default:content=home()}app.innerHTML=shell(content,path);const chat=$('#chat-panel');if(chat)chat.scrollTop=chat.scrollHeight;updateTimer()}
function updateTimer(){const el=$('[data-elapsed]');if(el&&data.active)el.textContent=fmtTime(elapsed(data.active))}
function reviewMark(id,rating){const old=data.reviews[id]||{count:0};data.reviews[id]={rating,count:(old.count||0)+1,updatedAt:new Date().toISOString()};save()}
function downloadData(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='parole-b2-mes-donnees.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function onAction(e){const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,day=Number(b.dataset.day),mode=b.dataset.mode;e.preventDefault();if(action==='flip'){ui.flipped=!ui.flipped;render();return}if(action==='speak-card'){const c=deck(Number(location.hash.split('/').at(-1)))[ui.cardIndex];speak(`${c.term}. ${c.example}`);return}if(action==='grade-card'){const d=Number(location.hash.split('/').at(-1)),cards=deck(d);reviewMark(cards[ui.cardIndex].id,b.dataset.grade);ui.flipped=false;if(ui.cardIndex<cards.length-1)ui.cardIndex++;else ui.cardDone=true;render();return}
if(action==='start-session'){startSession(day,mode);return}
if(action==='speak-last'){const a=data.active,s=a?.messages.filter(m=>m.role==='examiner').at(-1);if(s)speak(s.text);else if(a)speak(getTopic(a.day).prompt);return}
if(action==='toggle-mic'){toggleMic();return}
if(action==='send-answer'){await sendAnswer();return}
if(action==='end-session'){await finishSession();return}
if(action==='next-phase'){changePhase();return}
if(action==='toggle-pause'){const a=data.active;if(!a)return;if(a.pausedAt){a.pausedTotalMs+=Date.now()-a.pausedAt;a.pausedAt=null}else a.pausedAt=Date.now();save();render();return}
if(action==='reset-timer'){if(!confirm('Remettre le chronomètre à zéro pour cette étape ?'))return;const a=data.active;if(!a)return;a.phaseStartedAt=Date.now();a.pausedTotalMs=0;a.pausedAt=null;save();render();return}
if(action==='toggle-exam-text'){ui.showTextInExam=true;render();return}
if(action==='lesson-choice'){ui.lessonChoice=b.dataset.value;ui.checked=false;render();return}
if(action==='verify-choice'){ui.checked=true;render();return}
if(action==='next-exercise'){ui.exerciseIndex++;ui.lessonChoice=null;ui.checked=false;render();return}
if(action==='save-retry'){const text=$('#retry-text')?.value.trim();if(!text){toast('Écrivez ou dictez une nouvelle phrase.');return}const l=findLesson(b.dataset.id);if(l?.sessionId){const s=data.sessions.find(s=>s.id===l.sessionId);if(s){s.retries=s.retries||[];s.retries.push({text,at:new Date().toISOString()});save()}}ui.answerDraft='';toast('Votre phrase a été enregistrée. Continuez à vous entraîner.');render();return}
if(action==='retry-mic'){const area=$('#retry-text');if(!area)return;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){toast('Dictée non disponible. Vous pouvez écrire votre phrase.');return}const rec=new SR();rec.lang='fr-FR';rec.interimResults=false;rec.onresult=ev=>{area.value=(area.value+' '+ev.results[0][0].transcript).trim();ui.answerDraft=area.value};rec.onerror=()=>toast('Dictée indisponible.');try{rec.start();toast('Parlez maintenant…')}catch{toast('Impossible de démarrer la dictée.')}return}
if(action==='speak-review'){const seen=new Map(topics.flatMap(t=>deck(t.day)).map(c=>[c.id,c]));const arr=(ui.reviewQueue||[]).map(id=>seen.get(id)).filter(Boolean);const c=arr[ui.cardIndex];if(c)speak(`${c.term}. ${c.example}`);return}
if(action==='grade-review'){const seen=new Map(topics.flatMap(t=>deck(t.day)).map(c=>[c.id,c]));const arr=(ui.reviewQueue||[]).map(id=>seen.get(id)).filter(Boolean);const c=arr[ui.cardIndex];if(c)reviewMark(c.id,b.dataset.grade);ui.flipped=false;if(ui.cardIndex>=arr.length-1)ui.cardDone=true;else ui.cardIndex++;render();return}
if(action==='test-voice'){speak('Bonjour ! Je suis Camille, votre examinatrice. Aujourd’hui, nous allons parler français.');return}
if(action==='export'){downloadData();toast('Vos données ont été exportées.');return}
if(action==='clear-all'){if(confirm('Effacer définitivement toutes les séances, transcriptions, cartes et leçons enregistrées sur cet appareil ?')){stopMic();data=structuredClone(DEFAULT);save();location.hash='#/accueil';render();toast('Données locales effacées.')}return}}
app.addEventListener('click',onAction);
app.addEventListener('input',e=>{if(e.target?.id==='draft-input')ui.draft=e.target.value;if(e.target?.id==='retry-text')ui.answerDraft=e.target.value;if(e.target?.id==='rate'){data.preferences.rate=Number(e.target.value)/100;const v=$('#rate-value');if(v)v.textContent=e.target.value+' %';save()}if(e.target?.id==='auto-speak'){data.preferences.autoSpeak=e.target.checked;save()}});
app.addEventListener('keydown',e=>{if(e.target?.dataset?.action==='flip'&&(e.key==='Enter'||e.key===' ')){e.preventDefault();ui.flipped=!ui.flipped;render()}});
window.addEventListener('hashchange',render);window.addEventListener('beforeunload',()=>{stopMic();window.speechSynthesis?.cancel()});setInterval(updateTimer,1000);render();
fetch('/api/status').then(r=>r.ok?r.json():{aiAvailable:false}).then(v=>{const old=ui.aiAvailable;ui.aiAvailable=!!v.aiAvailable;ui.aiModel=v.model||'';if(old!==ui.aiAvailable)render()}).catch(()=>{});
